  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 School Vocabulary and Classroom Commands$j$, $j${"readings": [{"title": "Proverbs 4 (King James Version)", "url": "/portal/bible/Proverbs/4"}], "body": "Proverbs 4:7 says, Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding. School is a place to gain wisdom, and learning the words of the classroom helps you study in Spanish.\n\nPlaces and people at school include la escuela for school, el colegio for school or high school in many countries, el salón de clase for classroom, la biblioteca for library, el maestro and la maestra for teacher, el estudiante and la estudiante for student, el director and la directora for principal and el compañero and la compañera for classmate. School subjects include las matemáticas, el inglés, el español, la historia, la ciencia, la biología, el arte, la música, la educación física and la religión.\n\nClassroom objects include el libro, el cuaderno, el lápiz, el bolígrafo, la mochila, la computadora, la pizarra, el papel, la mesa and la silla. Use hay to say there is or there are. Hay un libro en la mesa. Hay veinte estudiantes en la clase. Hay does not change for singular or plural.\n\nTeachers use commands. The informal commands used in class include Escucha for listen, Lee for read, Escribe for write, Abre el libro for open the book, Cierra el cuaderno for close the notebook, Repite for repeat, Levanta la mano for raise your hand, Siéntate for sit down and Mira la pizarra for look at the board. Helpful classroom questions are ¿Cómo se dice en español? for how do you say it in Spanish, ¿Qué significa? for what does it mean, and No entiendo for I do not understand.\n\nYour task: (1) Name six school subjects and six classroom objects in Spanish. (2) Write four sentences with hay. (3) Write four classroom commands.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Proverbs 4:7 says, Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding.\n\nNow watch this. La escuela is school. El maestro and la maestra are teachers. El estudiante is the student. La biblioteca is the library. The subjects are las matemáticas, la historia, la ciencia, el inglés, el arte and la música.\n\nObjects are el libro, el cuaderno, el lápiz, la mochila, la computadora and la pizarra.\n\nUse hay for there is and there are. Hay un libro en la mesa. Hay veinte estudiantes en la clase.\n\nClassroom commands are escucha, lee, escribe, abre el libro, cierra el cuaderno, repite and levanta la mano. If you need help, say no entiendo or ¿Cómo se dice en español?\n\nYour task is to name subjects and objects, write four sentences with hay and write four commands. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 School Vocabulary and Classroom Commands$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Regular AR Verbs in the Present Tense$j$, $j${"readings": [{"title": "Colossians 3 (King James Version)", "url": "/portal/bible/Colossians/3"}], "body": "Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. Verbs are the action words of a language, and knowing how to use them lets you say what you do each day.\n\nSpanish verbs have an infinitive form that ends in ar, er or ir. To conjugate a regular ar verb, drop the ar and add the endings o, as, a, amos and an. For hablar, which means to speak or talk, the forms are yo hablo, tú hablas, él or ella or usted habla, nosotros hablamos and ellos or ellas or ustedes hablan. The verb ending shows who is doing the action, so Spanish speakers often leave out the subject pronoun. Hablo español means I speak Spanish.\n\nCommon regular ar verbs include estudiar for to study, trabajar for to work, caminar for to walk, cantar for to sing, escuchar for to listen, necesitar for to need, bailar for to dance, tocar for to play an instrument or touch, ayudar for to help, comprar for to buy, practicar for to practice, orar for to pray and llevar for to carry or wear.\n\nTo make a sentence negative, put no before the verb, as in No hablo francés. To ask a yes or no question, raise your voice or put the subject after the verb, as in ¿Estudias tú español? Often we simply say ¿Estudias español? To say what you do not do, use no. To say what someone does with an infinitive, use the conjugated verb first, as in Necesito estudiar.\n\nYour task: (1) Conjugate cantar for all subjects. (2) Write five sentences using different ar verbs. (3) Make two of them negative.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nNow watch this. Spanish infinitives end in ar, er or ir. For an ar verb, drop the ar and add o, as, a, amos, an. Hablar becomes hablo, hablas, habla, hablamos, hablan.\n\nThe ending tells who is acting, so we can often skip the pronoun. Hablo español means I speak Spanish.\n\nCommon ar verbs are estudiar, trabajar, caminar, cantar, escuchar, necesitar, bailar, ayudar, comprar and orar. To make a sentence negative, put no before the verb. No hablo francés. To use two verbs, conjugate the first. Necesito estudiar.\n\nYour task is to conjugate cantar and write five sentences, two of them negative. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Regular AR Verbs in the Present Tense$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Regular ER and IR Verbs in the Present Tense$j$, $j${"readings": [{"title": "Proverbs 2 (King James Version)", "url": "/portal/bible/Proverbs/2"}], "body": "Proverbs 2:6 says, For the LORD giveth wisdom: out of his mouth cometh knowledge and understanding. As you learn more verbs, you can say more about your life.\n\nTo conjugate a regular er verb, drop the er and add the endings o, es, e, emos and en. For comer, which means to eat, the forms are como, comes, come, comemos and comen. To conjugate a regular ir verb, drop the ir and add o, es, e, imos and en. For vivir, which means to live, the forms are vivo, vives, vive, vivimos and viven. The only difference between er and ir verbs is the nosotros form, which ends in emos for er verbs and imos for ir verbs.\n\nCommon er verbs include comer for to eat, beber for to drink, leer for to read, correr for to run, aprender for to learn, comprender for to understand, vender for to sell and creer for to believe. Common ir verbs include vivir for to live, escribir for to write, abrir for to open, recibir for to receive and asistir for to attend. Some verbs are regular except in the yo form, such as hacer, which means to do or make, with the yo form hago and the others hace, haces, hacemos and hacen, and ver, which means to see, with the yo form veo.\n\nYou can combine verbs with places and times. Vivo en Pompano Beach. Aprendemos español en la escuela. Leo la Biblia todos los días. Creo en Dios. Abrimos el libro.\n\nYour task: (1) Conjugate comer and vivir for all subjects. (2) Write five sentences using er and ir verbs. (3) Translate: I read the Bible every day.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Proverbs 2:6 says, For the LORD giveth wisdom: out of his mouth cometh knowledge and understanding.\n\nNow watch this. For er verbs, drop the er and add o, es, e, emos, en. Comer is como, comes, come, comemos, comen. For ir verbs, drop the ir and add o, es, e, imos, en. Vivir is vivo, vives, vive, vivimos, viven. Only the nosotros form is different.\n\nEr verbs include comer, beber, leer, correr, aprender and creer. Ir verbs include vivir, escribir, abrir, recibir and asistir. Hacer has hago in the yo form. Ver has veo.\n\nVivo en Pompano Beach. Aprendemos español en la escuela. Leo la Biblia todos los días.\n\nYour task is to conjugate comer and vivir, write five sentences and translate one. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Regular ER and IR Verbs in the Present Tense$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Telling Time and the Daily Schedule$j$, $j${"readings": [{"title": "Ecclesiastes 3 (King James Version)", "url": "/portal/bible/Ecclesiastes/3"}], "body": "Ecclesiastes 3:1 says, To every thing there is a season, and a time to every purpose under the heaven. Knowing how to tell time lets you plan your day and meet people on time in any language.\n\nTo ask the time, say ¿Qué hora es? For one o'clock, say Es la una. For all other hours, say Son las dos, Son las tres, Son las cuatro and so on. To add minutes, use y, as in Son las tres y diez, which is 3:10. A quarter past is y cuarto, as in Son las cinco y cuarto. Half past is y media, as in Son las seis y media. To subtract minutes, use menos, as in Son las ocho menos veinte, which is 7:40, and Son las doce menos cuarto, which is 11:45. Noon is el mediodía and midnight is la medianoche. Use de la mañana for AM until noon, de la tarde from noon until evening and de la noche at night.\n\nTo ask when something happens, say ¿A qué hora es la clase? and answer with a las, as in La clase es a las ocho de la mañana. For one o'clock, use a la una.\n\nWords about frequency help describe a schedule: siempre for always, todos los días for every day, a veces for sometimes, nunca for never, temprano for early, tarde for late, primero for first, luego for then and después for afterward.\n\nExample: Los lunes estudio en la escuela a las ocho. Luego como a las doce. Por la tarde ayudo en la iglesia. Por la noche leo la Biblia.\n\nYour task: (1) Write the times 2:00, 4:15, 6:30 and 9:45 in Spanish. (2) Write five sentences about your daily schedule.\n\nFlorida standards: Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 1 (WL.K12.NL, WL.K12.NM, WL.K12.NH)", "script": "Welcome back. Listen, Ecclesiastes 3:1 says, To every thing there is a season, and a time to every purpose under the heaven.\n\nNow watch this. ¿Qué hora es? asks what time is it. For one o'clock say es la una. For other hours say son las dos, son las tres, son las cuatro.\n\nAdd minutes with y. Son las tres y diez. Y cuarto is a quarter past. Y media is half past. Subtract with menos. Son las doce menos cuarto is 11:45.\n\nSay de la mañana, de la tarde or de la noche. To ask when a class is, say ¿A qué hora es la clase? Answer, es a las ocho de la mañana.\n\nFrequency words are siempre, todos los días, a veces, nunca, temprano and tarde.\n\nYour task is to write four times and five sentences about your schedule. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Telling Time and the Daily Schedule$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: School, Daily Life and Present Tense Verbs$j$, $j${"prompt": "Write a report of at least 250 words in English with Spanish examples. Use complete sentences and label each part. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nPart 1: List eight school words, six classroom commands and three uses of hay in Spanish.\nPart 2: Explain how to conjugate regular ar, er and ir verbs. Conjugate hablar, comer and vivir for all subjects.\nPart 3: Write a paragraph in Spanish of at least eight sentences describing your school day and daily schedule. Include at least four different verbs, three times and two frequency words.\nPart 4: Write ten times of day in Spanish, including quarter past, half past and quarter to.\nPart 5: Explain how Colossians 3:23 and Ecclesiastes 3:1 guide the way you study and use your time.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 25 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: School, Daily Life and Present Tense Verbs$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Do It Heartily, as to the Lord$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes your daily routine using at least five Spanish sentences from this unit, (2) explains how a regular habit of practice, even ten minutes a day, helps you learn a language, (3) names one way you can use your time wisely this week for study, service or prayer, and (4) connects your answer to Colossians 3:23, Proverbs 4:7 or Ecclesiastes 3:1. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why do you think regular verb patterns make a language easier to learn? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Do It Heartily, as to the Lord$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: School Vocabulary and Classroom Commands$j$, $j${"questions": [{"q": "La biblioteca is:", "options": ["The library", "The classroom", "The principal", "The bookstore"]}, {"q": "Hay veinte estudiantes means:", "options": ["Twenty students are tall", "There are twenty students", "I have twenty students", "I like students"]}, {"q": "Abre el libro means:", "options": ["Close the book", "Read the book", "Open the book", "Buy the book"]}, {"q": "No entiendo means:", "options": ["I do not know him", "I do not want it", "I do not understand", "I do not have it"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: School Vocabulary and Classroom Commands$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,2,2}'::int[], array[$j$Biblioteca means library.$j$,$j$Hay means there is or there are.$j$,$j$Abre is the command to open.$j$,$j$Entiendo comes from entender.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: School Vocabulary and Classroom Commands$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Regular AR Verbs in the Present Tense$j$, $j${"questions": [{"q": "The yo form of hablar is:", "options": ["Hablo", "Hablan", "Habla", "Hablas"]}, {"q": "Nosotros cantamos means:", "options": ["You sing", "They sing", "We sing", "I sing"]}, {"q": "To say I do not work, say:", "options": ["No trabajo", "Trabajo no", "Yo no trabajan", "No trabajas"]}, {"q": "Necesito estudiar means:", "options": ["I study", "I needed it", "I need to study", "He needs to study"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Regular AR Verbs in the Present Tense$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,0,2}'::int[], array[$j$Yo takes the o ending.$j$,$j$Amos is the nosotros ending.$j$,$j$Put no before the verb.$j$,$j$Necesito is the yo form of necesitar.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Regular AR Verbs in the Present Tense$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Regular ER and IR Verbs in the Present Tense$j$, $j${"questions": [{"q": "The nosotros form of vivir is:", "options": ["Vivís", "Vivimos", "Vivemos", "Viven"]}, {"q": "The ellos form of comer is:", "options": ["Comes", "Comemos", "Comen", "Come"]}, {"q": "Escribir means:", "options": ["To write", "To read", "To run", "To eat"]}, {"q": "The yo form of hacer is:", "options": ["Hacemos", "Hace", "Hazo", "Hago"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Regular ER and IR Verbs in the Present Tense$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,3}'::int[], array[$j$Ir verbs use imos.$j$,$j$Ellos takes en.$j$,$j$Escribir is to write.$j$,$j$Hacer is irregular in the yo form.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Regular ER and IR Verbs in the Present Tense$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Telling Time and the Daily Schedule$j$, $j${"questions": [{"q": "Es la una means:", "options": ["It is one thirty", "There is one", "It is eleven", "It is one o'clock"]}, {"q": "Son las seis y media means:", "options": ["It is 6:15", "It is 5:30", "It is 6:45", "It is 6:30"]}, {"q": "Son las doce menos cuarto is:", "options": ["11:45", "12:15", "12:45", "11:15"]}, {"q": "Nunca means:", "options": ["Always", "Sometimes", "Early", "Never"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Telling Time and the Daily Schedule$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,0,3}'::int[], array[$j$One o'clock uses the singular es la.$j$,$j$Media means half past.$j$,$j$Menos cuarto means a quarter to.$j$,$j$Nunca is never.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Telling Time and the Daily Schedule$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: School, Daily Life and Present Tense Verbs$j$, $j${"questions": [{"q": "El maestro is:", "options": ["The principal", "The teacher", "The student", "The library"]}, {"q": "Hay un lápiz en la mesa means:", "options": ["The pencil is red", "I have a pencil", "I like pencils", "There is a pencil on the table"]}, {"q": "The tú form of estudiar is:", "options": ["Estudian", "Estudio", "Estudias", "Estudia"]}, {"q": "The nosotros form of aprender is:", "options": ["Aprendimos", "Aprendemos", "Aprenden", "Aprendo"]}, {"q": "Ellos viven en Florida means:", "options": ["I live in Florida", "They live in Florida", "She lives in Florida", "We live in Florida"]}, {"q": "To say I do not understand, say:", "options": ["No tengo", "No hablo", "No entiendo", "No vivo"]}, {"q": "Son las ocho menos veinte is:", "options": ["7:40", "8:40", "7:20", "8:20"]}, {"q": "A veces means:", "options": ["Sometimes", "Every day", "Always", "Never"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: School, Daily Life and Present Tense Verbs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,2,1,1,2,0,0}'::int[], array[$j$Maestro is teacher.$j$,$j$Hay means there is.$j$,$j$Tú takes as.$j$,$j$Er verbs use emos.$j$,$j$Viven is the ellos form.$j$,$j$Entiendo is from entender.$j$,$j$Menos veinte means twenty to.$j$,$j$A veces is sometimes.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: School, Daily Life and Present Tense Verbs$j$ on conflict (item_id) do nothing;
